package com.bank.setops;

import java.util.*;
import java.util.logging.*;

public class SetOpsDemo {
    private static final Logger log = Logger.getLogger("SetOps");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<String> branchA = List.of("C1", "C2", "C3");
        List<String> branchB = List.of("C2", "C3", "C4");
        SetOpsService service = new SetOpsService();

        log.info(() -> "intersection: " + service.intersection(branchA, branchB));
        log.info(() -> "union       : " + service.union(branchA, branchB));
    }
}

// ─── Would be in service/SetOpsService.java ───
class SetOpsService {
    List<String> intersection(List<String> a, List<String> b) {
        Set<String> lookup = new HashSet<>(b);           // O(1) contains
        return a.stream()
            .filter(lookup::contains)                     // present in both
            .distinct()
            .toList();
    }

    List<String> union(List<String> a, List<String> b) {
        return java.util.stream.Stream.concat(a.stream(), b.stream())
            .distinct()                                   // every element once
            .toList();
    }
}
